export const plan = {
  unidad: "AWS-U0.1.2",
  falladas: ["aws-u0-1-2-quiz-02", "aws-u0-1-2-quiz-06"],
  repasos: [
    {
      id: "repaso-1",
      dia: 2,
      preguntas: ["aws-u0-1-2-quiz-02", "aws-u0-1-2-quiz-06"],
    },
    {
      id: "repaso-2",
      dia: 5,
      preguntas: ["aws-u0-1-2-quiz-02", "aws-u0-1-2-quiz-06"],
    },
    {
      id: "repaso-3",
      dia: 12,
      preguntas: ["aws-u0-1-2-quiz-02", "aws-u0-1-2-quiz-06"],
    },
  ],
};

spec.code:
for (let i = 1; i < plan.repasos.length; i += 1) {
  assert.ok(
    plan.repasos[i].dia > plan.repasos[i - 1].dia,
    plan.repasos[i].id + " no llega después que " + plan.repasos[i - 1].id,
  );
}

const falladas = [...plan.falladas].sort();
for (const repaso of plan.repasos) {
  assert.deepStrictEqual(
    [...repaso.preguntas].slice(0, falladas.length).sort(),
    falladas,
    repaso.id + " no empieza por las preguntas falladas",
  );
}

