// Sesión de repaso construida a partir de un registro de errores. Tiene un defecto principal.
export const sesion = {
  unidad: "AWS-U0.1.2",
  registro: [
    { pregunta: "aws-u0-1-2-quiz-02", fallos: 2, acertadaUltimaVez: false },
    { pregunta: "aws-u0-1-2-quiz-05", fallos: 0, acertadaUltimaVez: true },
    { pregunta: "aws-u0-1-2-quiz-06", fallos: 1, acertadaUltimaVez: false },
    { pregunta: "aws-u0-1-2-quiz-08", fallos: 0, acertadaUltimaVez: true },
  ],
  orden: [
    "aws-u0-1-2-quiz-05",
    "aws-u0-1-2-quiz-08",
    "aws-u0-1-2-quiz-02",
  ],
};

solution.code:
export const sesion = {
  unidad: "AWS-U0.1.2",
  registro: [
    { pregunta: "aws-u0-1-2-quiz-02", fallos: 2, acertadaUltimaVez: false },
    { pregunta: "aws-u0-1-2-quiz-05", fallos: 0, acertadaUltimaVez: true },
    { pregunta: "aws-u0-1-2-quiz-06", fallos: 1, acertadaUltimaVez: false },
    { pregunta: "aws-u0-1-2-quiz-08", fallos: 0, acertadaUltimaVez: true },
  ],
  orden: [
    "aws-u0-1-2-quiz-02",
    "aws-u0-1-2-quiz-06",
    "aws-u0-1-2-quiz-05",
    "aws-u0-1-2-quiz-08",
  ],
};

spec.code:
assert.deepStrictEqual(
  [...sesion.orden].sort(),
  sesion.registro.map((entrada) => entrada.pregunta).sort(),
  "el orden no coincide con las preguntas del registro",
);
assert.strictEqual(new Set(sesion.orden).size, sesion.orden.length, "el orden repite preguntas");

const pendientes = sesion.registro
  .filter((entrada) => !entrada.acertadaUltimaVez)
  .map((entrada) => entrada.pregunta);
const acertadas = sesion.registro
  .filter((entrada) => entrada.acertadaUltimaVez)
  .map((entrada) => entrada.pregunta);
const ultimaPendiente = Math.max(...pendientes.map((pregunta) => sesion.orden.indexOf(pregunta)));
const primeraAcertada = Math.min(...acertadas.map((pregunta) => sesion.orden.indexOf(pregunta)));
assert.ok(ultimaPendiente < primeraAcertada, "hay una pregunta pendiente después de una acertada");

const pendientes = sesion.registro
  .filter((entrada) => !entrada.acertadaUltimaVez)
  .sort((a, b) => b.fallos - a.fallos)
  .map((entrada) => entrada.pregunta);
const posiciones = pendientes.map((pregunta) => sesion.orden.indexOf(pregunta));
assert.deepStrictEqual(
  posiciones,
  [...posiciones].sort((a, b) => a - b),
  "las pendientes no están ordenadas por número de fallos",
);

assert.deepStrictEqual(sesion.registro, [
  { pregunta: "aws-u0-1-2-quiz-02", fallos: 2, acertadaUltimaVez: false },
  { pregunta: "aws-u0-1-2-quiz-05", fallos: 0, acertadaUltimaVez: true },
  { pregunta: "aws-u0-1-2-quiz-06", fallos: 1, acertadaUltimaVez: false },
  { pregunta: "aws-u0-1-2-quiz-08", fallos: 0, acertadaUltimaVez: true },
]);
